export function pickRandomBotName(random = Math.random, exclude = []) {
  const excluded = new Set(exclude.filter(Boolean));
  const pool = BOT_USERNAMES.filter((name) => !excluded.has(name));
  const source = pool.length ? pool : BOT_USERNAMES;
  if (!source.length) {
    return "Guest Player";
  }
  const index = Math.floor(random() * source.length);
  return source[Math.max(0, Math.min(source.length - 1, index))];
}

export function pickDistinctBotNames(count, random = Math.random) {
  const names = [];
  const used = new Set();
  for (let i = 0; i < count; i += 1) {
    const name = pickRandomBotName(random, [...used]);
    names.push(name);
    used.add(name);
  }
  return names;
}

function hashSeed(value) {
  const text = String(value || "");
  let hash = 2166136261;

  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }

  return hash >>> 0;
}

/** Stable name for a bot id so computer-mode labels do not flicker each render. */
export function pickStableBotName(seed, exclude = []) {
  const excluded = new Set(exclude.filter(Boolean));
  const pool = BOT_USERNAMES.filter((name) => !excluded.has(name));
  const source = pool.length ? pool : BOT_USERNAMES;

  if (!source.length) {
    return "Guest Player";
  }

  let index = hashSeed(seed) % source.length;
  for (let attempt = 0; attempt < source.length; attempt += 1) {
    const candidate = source[(index + attempt) % source.length];
    if (!excluded.has(candidate)) {
      return candidate;
    }
  }

  return source[index];
}

